3820|static BOOL
3821|read_pattern_file(char *name, patstr **patptr, patstr **patlastptr)
3822|{
3823|int linenumber = 0;
3824|PCRE2_SIZE patlen;
3825|FILE *f;
3826|const char *filename;
3827|char buffer[MAXPATLEN+20];
3828|
3829|if (strcmp(name, "-") == 0)
3830|  {
3831|  f = stdin;
3832|  filename = stdin_name;
3833|  }
3834|else
3835|  {
3836|  f = fopen(name, "r");
3837|  if (f == NULL)
3838|    {
3839|    fprintf(stderr, "pcre2grep: Failed to open %s: %s\n", name, strerror(errno));
3840|    return FALSE;
3841|    }
3842|  filename = name;
3843|  }
3844|
3845|while ((patlen = sizeof(buffer)) && read_pattern(buffer, &patlen, f))
3846|  {
3847|  if (!posix_pattern_file)
3848|   {
3849|   while (patlen > 0 && isspace((unsigned char)(buffer[patlen-1]))) patlen--;
3850|   }
3851|
3852|  linenumber++;
3853|  if (!posix_pattern_file && patlen == 0) continue; /* Skip blank lines */
3854|
3855|  /* Note: this call to add_pattern() puts a pointer to the local variable
3856|  "buffer" into the pattern chain. However, that pointer is used only when
3857|  compiling the pattern, which happens immediately below, so we flatten it
3858|  afterwards, as a precaution against any later code trying to use it. */
3859|
3860|  *patlastptr = add_pattern(buffer, patlen, *patlastptr);
3861|  if (*patlastptr == NULL)
3862|    {
3863|    /* LCOV_EXCL_START - won't happen in testing */
3864|    if (f != stdin) fclose(f);
3865|    return FALSE;
3866|    /* LCOV_EXCL_STOP */
3867|    }
3868|  if (*patptr == NULL) *patptr = *patlastptr;
3869|
3870|  /* This loop is needed because compiling a "pattern" when -F is set may add
3871|  on additional literal patterns if the original contains a newline. In the
3872|  common case, it never will, because read_one_line() stops at a newline.
3873|  However, the -N option can be used to give pcre2grep a different newline
3874|  setting. */
3875|
3876|  for(;;)
3877|    {
3878|    if (!compile_pattern(*patlastptr, pcre2_options, TRUE, filename,
3879|        linenumber))
3880|      {
3881|      if (f != stdin) fclose(f);
3882|      return FALSE;
3883|      }
3884|    (*patlastptr)->string = NULL;            /* Insurance */
3885|    if ((*patlastptr)->next == NULL) break;
3886|    *patlastptr = (*patlastptr)->next;
3887|    }
3888|  }
3889|
3890|if (f != stdin) fclose(f);
3891|return TRUE;
3892|}

