9680|
9681|    /* Otherwise, if we are not skipping, and the line is not a data comment
9682|    line starting with "\=", process a data line. */
9683|
9684|    else if (!skipping && !(p[0] == '\\' && p[1] == '=' && isspace(p[2])))
9685|      {
