198|static BOOL
199|check_char_prop(uint32_t c, unsigned int ptype, unsigned int pdata,
200|  BOOL negated)
201|{
202|BOOL ok;
203|const uint32_t *p;
204|const ucd_record *prop = GET_UCD(c);
205|
206|switch(ptype)
207|  {
208|  case PT_LAMP:
209|  return (prop->chartype == ucp_Lu ||
210|          prop->chartype == ucp_Ll ||
211|          prop->chartype == ucp_Lt) == negated;
212|
213|  case PT_GC:
214|  return (pdata == PRIV(ucp_gentype)[prop->chartype]) == negated;
215|
216|  case PT_PC:
217|  return (pdata == prop->chartype) == negated;
218|
219|  case PT_SC:
220|  return (pdata == prop->script) == negated;
221|
222|  case PT_SCX:
223|  ok = (pdata == prop->script
224|        || MAPBIT(PRIV(ucd_script_sets) + UCD_SCRIPTX_PROP(prop), pdata) != 0);
225|  return ok == negated;
226|
227|  /* These are specials */
228|
229|  case PT_ALNUM:
230|  return (PRIV(ucp_gentype)[prop->chartype] == ucp_L ||
231|          PRIV(ucp_gentype)[prop->chartype] == ucp_N) == negated;
232|
233|  /* Perl space used to exclude VT, but from Perl 5.18 it is included, which
234|  means that Perl space and POSIX space are now identical. PCRE was changed
235|  at release 8.34. */
236|
237|  case PT_SPACE:    /* Perl space */
238|  case PT_PXSPACE:  /* POSIX space */
239|  switch(c)
240|    {
241|    HSPACE_CASES:
242|    VSPACE_CASES:
243|    return negated;
244|
245|    default:
246|    return (PRIV(ucp_gentype)[prop->chartype] == ucp_Z) == negated;
247|    }
248|  PCRE2_UNREACHABLE(); /* Control never reaches here */
249|  break;
250|
251|  case PT_WORD:
252|  return (PRIV(ucp_gentype)[prop->chartype] == ucp_L ||
253|          PRIV(ucp_gentype)[prop->chartype] == ucp_N ||
254|          c == CHAR_UNDERSCORE) == negated;
255|
256|  case PT_CLIST:
257|  p = PRIV(ucd_caseless_sets) + prop->caseset;
258|  for (;;)
259|    {
260|    if (c < *p) return !negated;
261|    if (c == *p++) return negated;
262|    }
263|  PCRE2_UNREACHABLE(); /* Control never reaches here */
264|  break;
265|
266|  /* Haven't yet thought these through. */
267|
268|  case PT_BIDICL:
269|  return FALSE;
270|
271|  case PT_BOOL:
272|  return FALSE;
273|  }
274|
275|return FALSE;
276|}

326|static PCRE2_SPTR
327|get_chr_property_list(PCRE2_SPTR code, BOOL utf, BOOL ucp, const uint8_t *fcc,
328|  uint32_t *list)
329|{
330|PCRE2_UCHAR c = *code;
331|PCRE2_UCHAR base;
332|PCRE2_SPTR end;
333|uint32_t chr;
334|
335|#ifdef SUPPORT_UNICODE
336|uint32_t *clist_dest;
337|const uint32_t *clist_src;
338|#else
339|(void)utf;    /* Suppress "unused parameter" compiler warnings */
340|(void)ucp;
341|#endif
342|
343|list[0] = c;
344|list[1] = FALSE;
345|code++;
346|
347|if (c >= OP_STAR && c <= OP_TYPEPOSUPTO)
348|  {
349|  base = get_repeat_base(c);
350|  c -= (base - OP_STAR);
351|
352|  if (c == OP_UPTO || c == OP_MINUPTO || c == OP_EXACT || c == OP_POSUPTO)
353|    code += IMM2_SIZE;
354|
355|  list[1] = (c != OP_PLUS && c != OP_MINPLUS && c != OP_EXACT &&
356|             c != OP_POSPLUS);
357|
358|  switch(base)
359|    {
360|    case OP_STAR:
361|    list[0] = OP_CHAR;
362|    break;
363|
364|    case OP_STARI:
365|    list[0] = OP_CHARI;
366|    break;
367|
368|    case OP_NOTSTAR:
369|    list[0] = OP_NOT;
370|    break;
371|
372|    case OP_NOTSTARI:
373|    list[0] = OP_NOTI;
374|    break;
375|
376|    case OP_TYPESTAR:
377|    list[0] = *code;
378|    code++;
379|    break;
380|    }
381|  c = list[0];
382|  }
383|
384|switch(c)
385|  {
386|  case OP_NOT_DIGIT:
387|  case OP_DIGIT:
388|  case OP_NOT_WHITESPACE:
389|  case OP_WHITESPACE:
390|  case OP_NOT_WORDCHAR:
391|  case OP_WORDCHAR:
392|  case OP_ANY:
393|  case OP_ALLANY:
394|  case OP_ANYNL:
395|  case OP_NOT_HSPACE:
396|  case OP_HSPACE:
397|  case OP_NOT_VSPACE:
398|  case OP_VSPACE:
399|  case OP_EXTUNI:
400|  case OP_EODN:
401|  case OP_EOD:
402|  case OP_DOLL:
403|  case OP_DOLLM:
404|  return code;
405|
406|  case OP_CHAR:
407|  case OP_NOT:
408|  GETCHARINCTEST(chr, code);
409|  list[2] = chr;
410|  list[3] = NOTACHAR;
411|  return code;
412|
413|  case OP_CHARI:
414|  case OP_NOTI:
415|  list[0] = (c == OP_CHARI) ? OP_CHAR : OP_NOT;
416|  GETCHARINCTEST(chr, code);
417|  list[2] = chr;
418|
419|#ifdef SUPPORT_UNICODE
420|  if (chr < 128 || (chr < 256 && !utf && !ucp))
421|    list[3] = fcc[chr];
422|  else
423|    list[3] = UCD_OTHERCASE(chr);
424|#elif defined SUPPORT_WIDE_CHARS
425|  list[3] = (chr < 256) ? fcc[chr] : chr;
426|#else
427|  list[3] = fcc[chr];
428|#endif
429|
430|  /* The othercase might be the same value. */
431|
432|  if (chr == list[3])
433|    list[3] = NOTACHAR;
434|  else
435|    list[4] = NOTACHAR;
436|  return code;
437|
438|#ifdef SUPPORT_UNICODE
439|  case OP_PROP:
440|  case OP_NOTPROP:
441|  if (code[0] != PT_CLIST)
442|    {
443|    list[2] = code[0];
444|    list[3] = code[1];
445|    return code + 2;
446|    }
447|
448|  /* Convert only if we have enough space. */
449|
450|  clist_src = PRIV(ucd_caseless_sets) + code[1];
451|  clist_dest = list + 2;
452|  code += 2;
453|
454|  do {
455|     if (clist_dest >= list + 8)
456|       {
457|       /* Early return if there is not enough space. This should never
458|       happen, since all clists are shorter than 5 character now. */
459|       list[2] = code[0];
460|       list[3] = code[1];
461|       return code;
462|       }
463|     *clist_dest++ = *clist_src;
464|     }
465|  while(*clist_src++ != NOTACHAR);
466|
467|  /* All characters are stored. The terminating NOTACHAR is copied from the
468|  clist itself. */
469|
470|  list[0] = (c == OP_PROP) ? OP_CHAR : OP_NOT;
471|  return code;
472|#endif
473|
474|  case OP_NCLASS:
475|  case OP_CLASS:
476|#ifdef SUPPORT_WIDE_CHARS
477|  case OP_XCLASS:
478|  if (c == OP_XCLASS)
479|    end = code + GET(code, 0) - 1;
480|  else
481|#endif
482|    end = code + 32 / sizeof(PCRE2_UCHAR);
483|
484|  switch(*end)
485|    {
486|    case OP_CRSTAR:
487|    case OP_CRMINSTAR:
488|    case OP_CRQUERY:
489|    case OP_CRMINQUERY:
490|    case OP_CRPOSSTAR:
491|    case OP_CRPOSQUERY:
492|    list[1] = TRUE;
493|    end++;
494|    break;
495|
496|    case OP_CRPLUS:
497|    case OP_CRMINPLUS:
498|    case OP_CRPOSPLUS:
499|    end++;
500|    break;
501|
502|    case OP_CRRANGE:
503|    case OP_CRMINRANGE:
504|    case OP_CRPOSRANGE:
505|    list[1] = (GET2(end, 1) == 0);
506|    end += 1 + 2 * IMM2_SIZE;
507|    break;
508|    }
509|  list[2] = (uint32_t)(end - code);
510|  return end;
511|  }
512|
513|return NULL;    /* Opcode not accepted */
514|}

537|static BOOL
538|compare_opcodes(PCRE2_SPTR code, BOOL utf, BOOL ucp, const compile_block *cb,
539|  const uint32_t *base_list, PCRE2_SPTR base_end, int *rec_limit)
540|{
541|PCRE2_UCHAR c;
542|uint32_t list[8];
543|const uint32_t *chr_ptr;
544|const uint32_t *ochr_ptr;
545|const uint32_t *list_ptr;
546|PCRE2_SPTR next_code;
547|#ifdef SUPPORT_WIDE_CHARS
548|PCRE2_SPTR xclass_flags;
549|#endif
550|const uint8_t *class_bitset;
551|const uint8_t *set1, *set2, *set_end;
552|uint32_t chr;
553|BOOL accepted, invert_bits;
554|BOOL entered_a_group = FALSE;
555|
556|if (--(*rec_limit) <= 0) return FALSE;  /* Recursion has gone too deep */
557|
558|/* Note: the base_list[1] contains whether the current opcode has a greedy
559|(represented by a non-zero value) quantifier. This is a different from
560|other character type lists, which store here that the character iterator
561|matches to an empty string (also represented by a non-zero value). */
562|
563|for(;;)
564|  {
565|  PCRE2_SPTR bracode;
566|
567|  /* All operations move the code pointer forward.
568|  Therefore infinite recursions are not possible. */
569|
570|  c = *code;
571|
572|  /* Skip over callouts */
573|
574|  if (c == OP_CALLOUT)
575|    {
576|    code += PRIV(OP_lengths)[c];
577|    continue;
578|    }
579|
580|  if (c == OP_CALLOUT_STR)
581|    {
582|    code += GET(code, 1 + 2*LINK_SIZE);
583|    continue;
584|    }
585|
586|  /* At the end of a branch, skip to the end of the group and process it. */
587|
588|  if (c == OP_ALT)
589|    {
590|    do code += GET(code, 1); while (*code == OP_ALT);
591|    c = *code;
592|    }
593|
594|  /* Inspect the next opcode. */
595|
596|  switch(c)
597|    {
598|    /* We can always possessify a greedy iterator at the end of the pattern,
599|    which is reached after skipping over the final OP_KET. A non-greedy
600|    iterator must never be possessified. */
601|
602|    case OP_END:
603|    return base_list[1] != 0;
604|
605|    /* When an iterator is at the end of certain kinds of group we can inspect
606|    what follows the group by skipping over the closing ket. Note that this
607|    does not apply to OP_KETRMAX or OP_KETRMIN because what follows any given
608|    iteration is variable (could be another iteration or could be the next
609|    item). As these two opcodes are not listed in the next switch, they will
610|    end up as the next code to inspect, and return FALSE by virtue of being
611|    unsupported. */
612|
613|    case OP_KET:
614|    case OP_KETRPOS:
615|    /* The non-greedy case cannot be converted to a possessive form. */
616|
617|    if (base_list[1] == 0) return FALSE;
618|
619|    /* If the bracket is capturing it might be referenced by an OP_RECURSE
620|    so its last iterator can never be possessified if the pattern contains
621|    recursions. (This could be improved by keeping a list of group numbers that
622|    are called by recursion.) */
623|
624|    bracode = code - GET(code, 1);
625|    switch(*bracode)
626|      {
627|      case OP_CBRA:
628|      case OP_SCBRA:
629|      case OP_CBRAPOS:
630|      case OP_SCBRAPOS:
631|      if (cb->had_recurse) return FALSE;
632|      break;
633|
634|      /* A script run might have to backtrack if the iterated item can match
635|      characters from more than one script. So give up unless repeating an
636|      explicit character. */
637|
638|      case OP_SCRIPT_RUN:
639|      if (base_list[0] != OP_CHAR && base_list[0] != OP_CHARI)
640|        return FALSE;
641|      break;
642|
